<?php
define('INNOVATRONICA_AJUSTES_API',true);require __DIR__.'/../includes/ajustes.php';
function stock_expirar(PDO $pdo):int{return 0;}
class AjustePDO extends PDO {public string $fallar=''; public function prepare(string $s,array $o=[]):PDOStatement|false {if($this->fallar&&str_contains($s,$this->fallar))throw new PDOException('Simulado');return parent::prepare(str_replace(' FOR UPDATE','',$s),$o);}}
$db=new AjustePDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->exec("CREATE TABLE productos(sku TEXT,nombre TEXT);CREATE TABLE inventario(sku TEXT PRIMARY KEY,stock_fisico INT);CREATE TABLE reservas(sku TEXT,cantidad INT,estado TEXT);CREATE TABLE movimientos_stock(sku TEXT,tipo TEXT,cantidad INT,stock_anterior INT,stock_nuevo INT,id_empleado INT,motivo TEXT);CREATE TABLE log_acciones(id_empleado INT,accion TEXT,detalles TEXT,ip TEXT);INSERT INTO productos VALUES('A','Sensor');INSERT INTO inventario VALUES('A',10);INSERT INTO reservas VALUES('A',4,'ACTIVA');");
$n=0;function check($x,$m){global $n;if(!$x)throw new Exception($m);$n++;}
$r=ajuste_consultar($db,['sku'=>'A']);check($r['producto']['stock_fisico']===10&&$r['producto']['comprometido']===4,'Consulta');
$p=['sku'=>'A','stock_nuevo'=>'15','stock_esperado'=>'10','motivo'=>'Compra','tipo'=>'INGRESO'];$r=ajuste_guardar($db,$p,1);check($r['nuevo']===15,'Ingreso');$m=$db->query('SELECT * FROM movimientos_stock')->fetch(PDO::FETCH_ASSOC);check($m['tipo']==='INGRESO'&&(int)$m['cantidad']===5&&(int)$m['stock_anterior']===10&&(int)$m['stock_nuevo']===15,'Movimiento');
$p=['sku'=>'A','stock_nuevo'=>'4','stock_esperado'=>'15','motivo'=>'Recuento','tipo'=>'AJUSTE'];$r=ajuste_guardar($db,$p,1);check($r['nuevo']===4,'Mínimo comprometido permitido');
$bad=[['sku'=>'A','stock_nuevo'=>3,'stock_esperado'=>4,'motivo'=>'Recuento','tipo'=>'AJUSTE'],['sku'=>'A','stock_nuevo'=>6,'stock_esperado'=>5,'motivo'=>'Compra','tipo'=>'INGRESO'],['sku'=>'A','stock_nuevo'=>3,'stock_esperado'=>4,'motivo'=>'Compra','tipo'=>'INGRESO'],['sku'=>'A','stock_nuevo'=>4,'stock_esperado'=>4,'motivo'=>'Nada','tipo'=>'AJUSTE'],['sku'=>'A','stock_nuevo'=>5,'stock_esperado'=>4,'motivo'=>'  ','tipo'=>'AJUSTE'],['sku'=>'A','stock_nuevo'=>'1.2','stock_esperado'=>4,'motivo'=>'x','tipo'=>'AJUSTE'],['sku'=>'X','stock_nuevo'=>5,'stock_esperado'=>4,'motivo'=>'x','tipo'=>'AJUSTE']];foreach($bad as $p){try{ajuste_guardar($db,$p,1);throw new Exception('Aceptó operación inválida');}catch(AjusteError $e){check(true,'Rechazado');}}
$db->fallar='INSERT INTO log_acciones';try{ajuste_guardar($db,['sku'=>'A','stock_nuevo'=>7,'stock_esperado'=>4,'motivo'=>'X','tipo'=>'INGRESO'],1);throw new Exception('Sin fallo');}catch(PDOException $e){}check((int)$db->query("SELECT stock_fisico FROM inventario WHERE sku='A'")->fetchColumn()===4,'Rollback físico');check((int)$db->query('SELECT COUNT(*) FROM movimientos_stock')->fetchColumn()===2,'Rollback movimiento');check(!$db->inTransaction(),'Transacción cerrada');echo "OK: $n verificaciones de ajustes.\n";
